#include "topology.hpp"
#include <sched.h>
inline int process_threads(){std::ifstream f("/proc/self/status");std::string l;while(std::getline(f,l))if(l.rfind("Threads:",0)==0)return std::stoi(l.substr(8));throw std::runtime_error("threads missing");}
inline void threads(){for(auto key:{"OMP_NUM_THREADS","OPENBLAS_NUM_THREADS","MKL_NUM_THREADS"}){const char* v=getenv(key);require(v&&std::string(v)=="1",std::string(key)+" must be 1");}omp_set_dynamic(0);omp_set_num_threads(1);require(process_threads()==1,"process not single threaded");cpu_set_t set;CPU_ZERO(&set);require(sched_getaffinity(0,sizeof(set),&set)==0&&CPU_COUNT(&set)==1&&CPU_ISSET(15,&set),"CPU15 required");}
struct CountDC:faiss::DistanceComputer{std::unique_ptr<faiss::DistanceComputer> dc;uint64_t count=0;std::array<int32_t,3> first;
 explicit CountDC(faiss::DistanceComputer* p):dc(p){}void set_query(const float* q)override{count=0;dc->set_query(q);}float operator()(faiss::idx_t i)override{if(count<3)first[count]=i;++count;return (*dc)(i);}float symmetric_dis(faiss::idx_t i,faiss::idx_t j)override{return dc->symmetric_dis(i,j);}};
struct CountParam{hnswlib::DISTFUNC<float> fn;void* param;uint64_t n=0;};
float counted(const void*a,const void*b,const void*p){auto* c=(CountParam*)p;++c->n;return c->fn(a,b,c->param);}
struct Router{
 std::string method;size_t d;std::vector<int32_t> ids;std::vector<float> w,qnorm;hnswlib::InnerProductSpace space;std::unique_ptr<HNSW> graph;CountParam counter;
 Router(const json& c,size_t dim,const fs::path& out):method(c["name"]),d(dim),space(d),counter{space.get_dist_func(),space.get_dist_func_param(),0}{
 ids=read_raw<int32_t>(c["ids"].get<std::string>());w=read_raw<float>(c["W"].get<std::string>());require(w.size()==ids.size()*d,"router shape");require(std::set<int32_t>(ids.begin(),ids.end()).size()==ids.size(),"unique real hubs");qnorm.resize(d);bool gate=method=="GATE";graph=std::make_unique<HNSW>(&space,ids.size(),gate?256:16,gate?256:200,gate?100:20260828);for(size_t i=0;i<ids.size();++i)graph->addPoint(w.data()+i*d,gate?i:ids[i]);graph->setEf(10);if(fs::exists(out))graph=std::make_unique<HNSW>(&space,out.string(),false,ids.size());else graph->saveIndex(out.string());graph->setEf(10);
 for(size_t i=0;i<ids.size();++i){require(graph->getExternalLabel(i)==size_t(gate?i:ids[i]),"route graph label");require(std::memcmp(graph->getDataByInternalId(i),w.data()+i*d,d*4)==0,"route graph vector bits");}}
 void counting(bool yes){graph->fstdistfunc_=yes?counted:space.get_dist_func();graph->dist_func_param_=yes?(void*)&counter:space.get_dist_func_param();}
 std::array<int32_t,3> route(const float* q){const float* use=q;if(method=="GATE"){std::copy(q,q+d,qnorm.begin());normalize(qnorm.data(),d);use=qnorm.data();}counter.n=0;auto heap=graph->searchKnn(use,3);require(heap.size()==3,"three routes");std::array<int32_t,3> r;for(int j=0;j<3;++j){r[j]=method=="GATE"?ids[heap.top().second]:heap.top().second;heap.pop();}if(method!="GATE")std::sort(r.begin(),r.end());return r;}
};
struct Batch{size_t n,k;std::vector<int32_t> ids,entries;std::vector<float> dist;std::vector<uint64_t> route_ndc,graph_ndc;explicit Batch(size_t count,size_t topk):n(count),k(topk),ids(n*k),entries(n*3,-1),dist(n*k),route_ndc(n),graph_ndc(n){}};
void same(const Batch&a,const Batch&b){require(a.n==b.n&&a.k==b.k&&a.ids==b.ids&&a.entries==b.entries&&std::memcmp(a.dist.data(),b.dist.data(),a.dist.size()*4)==0,"batch ID/entry/distance bit mismatch");}
void save_batch(const fs::path& out,const Batch& b,bool count){fs::create_directories(out);if(!count){write_raw(out/"ids.i32",b.ids);write_raw(out/"distances.f32",b.dist);write_raw(out/"entry_ids.i32",b.entries);}else{write_raw(out/"route_ndc.u64",b.route_ndc);write_raw(out/"graph_ndc.u64",b.graph_ndc);}}
struct Worker{acsg::IndexACSGFlat& index;std::unique_ptr<faiss::DistanceComputer> plain;CountDC counter;faiss::VisitedTable vt;std::vector<acsg::Neighbor> ret;std::vector<acsg::EnterPoint> ep;std::array<faiss::idx_t,100> ids;
 explicit Worker(acsg::IndexACSGFlat& idx):index(idx),plain(acsg::storage_distance_computer(idx.storage)),counter(acsg::storage_distance_computer(idx.storage)),vt(idx.ntotal){ret.reserve(1501);ep.reserve(3);}
 void run(const std::string& method,Router* router,HNSW* full,CountParam& hc,const std::vector<float>& q,size_t d,Batch& b,bool count){auto& dc=count?static_cast<faiss::DistanceComputer&>(counter):*plain;
 for(size_t i=0;i<b.n;++i){auto query=q.data()+i*d;
 if(method=="HNSW"){hc.n=0;auto heap=full->searchKnn(query,b.k);require(heap.size()==b.k,"full HNSW result size");for(int j=int(b.k)-1;j>=0;--j){b.ids[i*b.k+j]=heap.top().second;b.dist[i*b.k+j]=heap.top().first;heap.pop();}if(count)b.graph_ndc[i]=hc.n;continue;}
 std::array<int32_t,3> entries{-1,-1,-1};size_t k=1;if(router){entries=router->route(query);k=3;}else entries[0]=index.acsg.enterpoint;
 std::copy(entries.begin(),entries.end(),b.entries.begin()+i*3);ep.clear();for(size_t j=0;j<k;++j)ep.emplace_back(entries[j],1.);vt.advance();dc.set_query(query);index.acsg.search_new(dc,b.k,ids.data(),b.dist.data()+i*b.k,vt,2,ep,&ret);for(size_t j=0;j<b.k;++j)b.ids[i*b.k+j]=ids[j];if(count){b.graph_ndc[i]=counter.count;b.route_ndc[i]=router?router->counter.n:0;for(size_t j=0;j<k;++j)require(counter.first[j]==entries[j],"entry injection order mismatch");}}
 }};
int main(int argc,char**argv){try{require(argc==3,"evaluate config new_output");threads();json c=read_json(argv[1]);fs::path out=argv[2];if(fs::exists(out)){require(read_json(out/"config.json")==c,"resume configuration changed");if(fs::exists(out/"complete.json"))return 0;if(fs::exists(out/"timing_progress.json")){auto archive=out/"incomplete_attempts";fs::create_directories(archive);fs::copy_file(out/"timing_progress.json",archive/("timing_progress_"+std::to_string(std::time(nullptr))+".json"));}}else{fs::create_directories(out);write_json(out/"config.json",c);}bool formal=c.value("formal",false);int reps=formal?3:1;require(c["threads"]==1,"threads config");auto idx=load_nsg(c["index"]);size_t d=idx->d,n=c["n"],K=c["K"];int metric=c["metric_id"];require((K==1||K==100)&&idx->metric_type==metric,"K/metric contract");std::vector<float> q;
 if(formal){Fvecs fq(c["queries"]);require(fq.n==n&&n>0&&fq.d==d,"test queries shape");q.resize(n*d);for(size_t i=0;i<n;++i)std::copy(fq.row(i),fq.row(i)+d,q.begin()+i*d);}else q=read_raw<float>(c["queries"].get<std::string>());require(q.size()==n*d,"query shape");for(float x:q)require(std::isfinite(x),"nonfinite query");
 std::map<std::string,std::unique_ptr<Router>> routers;std::vector<std::string> names;for(auto m:c["methods"]){std::string name=m["name"];names.push_back(name);if(name!="NSG"&&name!="HNSW")routers[name]=std::make_unique<Router>(m,d,out/(name+".hnsw"));}
 std::unique_ptr<Fvecs> base;auto full_space=make_space(metric,d);CountParam hc{full_space->get_dist_func(),full_space->get_dist_func_param(),0};std::unique_ptr<HNSW> full;
 if(std::find(names.begin(),names.end(),"HNSW")!=names.end()){auto hm=read_json(c["hnsw_complete"].get<std::string>());require(hm["status"]=="PASS"&&hm["metric_id"]==metric,"full HNSW metric/verification");base=std::make_unique<Fvecs>(c["base"]);full=load_topology(c["hnsw_topology"].get<std::string>(),*base,full_space.get());}
 resources(out);threads();Worker worker(*idx);Batch warm(n,K),timed(n,K),count(n,K);std::map<std::string,std::unique_ptr<Batch>> reference;std::map<std::string,std::vector<double>> timings;json progress=json::array();auto run=[&](const std::string& name,Batch& b,bool counting){Router* router=routers.count(name)?routers.at(name).get():nullptr;if(router)router->counting(counting);if(name=="HNSW"){full->fstdistfunc_=counting?counted:full_space->get_dist_func();full->dist_func_param_=counting?(void*)&hc:full_space->get_dist_func_param();}worker.run(name,router,full.get(),hc,q,d,b,counting);};
 // Reset reusable outputs on method changes outside the measured section.
 auto clear=[&](Batch& b){std::fill(b.entries.begin(),b.entries.end(),-1);std::fill(b.route_ndc.begin(),b.route_ndc.end(),0);std::fill(b.graph_ndc.begin(),b.graph_ndc.end(),0);};
 std::ifstream boot_file("/proc/sys/kernel/random/boot_id");std::string boot;std::getline(boot_file,boot);json boot_ids=json::array();
 int ordinal=0;for(int L:c["L"]){require(L>=int(K)&&L<=1500,"L bounds");bool all_done=true;for(const auto& name:names)all_done=all_done&&fs::exists(out/(name+"_L"+std::to_string(L))/"complete.json");
 if(all_done){for(const auto& name:names){auto old=read_json(out/(name+"_L"+std::to_string(L))/"complete.json");require(old["status"]=="PASS"&&old["threads"]==1&&old["n"]==n&&old["K"]==K&&old["metric_id"]==metric&&old["seconds"].size()==size_t(reps),"resume completed point contract");for(int rep=0;rep<reps;++rep)progress.push_back({{"method",name},{"L",L},{"repeat",rep},{"seconds",old["seconds"][rep]},{"qps",n/old["seconds"][rep].get<double>()},{"process_threads",1},{"formal",formal},{"boot_id",old.value("boot_id",std::string("legacy"))}});}++ordinal;continue;}
 for(const auto& name:names){auto partial=out/(name+"_L"+std::to_string(L));if(fs::exists(partial)){auto archive=out/"incomplete_attempts"/(boot+"_"+std::to_string(std::time(nullptr)));fs::create_directories(archive);fs::rename(partial,archive/partial.filename());}}
 idx->acsg.search_L=L;if(full)full->setEf(L);
 for(int rep=0;rep<reps;++rep){auto order=names;size_t offset=(ordinal+rep+c.value("dataset_order",0))%order.size();std::rotate(order.begin(),order.begin()+offset,order.end());
 for(const auto& name:order){std::string key=name+"_L"+std::to_string(L);clear(timed);if(rep==0){clear(warm);run(name,warm,false);}threads();auto t=Clock::now();run(name,timed,false);double elapsed=seconds(t);if(rep==0){same(warm,timed);reference[key]=std::make_unique<Batch>(timed);save_batch(out/key,timed,false);}else same(*reference[key],timed);timings[key].push_back(elapsed);json p={{"method",name},{"L",L},{"repeat",rep},{"seconds",elapsed},{"qps",n/elapsed},{"process_threads",process_threads()},{"formal",formal},{"boot_id",boot}};progress.push_back(p);write_json(out/"timing_progress.json",progress);std::cout<<p.dump()<<std::endl;}}
 for(const auto& name:names){std::string key=name+"_L"+std::to_string(L);clear(count);run(name,count,true);same(*reference[key],count);save_batch(out/key,count,true);write_json(out/key/"complete.json",{{"status","PASS"},{"K",K},{"metric_id",metric},{"L",L},{"method",name},{"n",n},{"seconds",timings[key]},{"plain_count_bit_parity",true},{"warmup_bit_parity",true},{"threads",1},{"cpu",15},{"boot_id",boot}});reference.erase(key);}++ordinal;}
 write_json(out/"timing_progress.json",progress);write_json(out/"complete.json",{{"status","PASS"},{"K",K},{"metric_id",metric},{"points",ordinal*names.size()},{"wall_rounds",ordinal*names.size()*reps},{"threads",1},{"process_threads",process_threads()},{"formal",formal}});return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
